import heapq


def countWithinBudget(n, roads, src, budget):
    adj = [[] for _ in range(n)]
    for a, b, w in roads:
        adj[a].append((b, w))
        adj[b].append((a, w))
    best = [float('inf')] * n
    best[src] = 0
    heap = [(0, src)]
    count = 0
    while heap:
        d, u = heapq.heappop(heap)
        if d > best[u]:
            continue
        if d > budget:
            break
        count += 1
        for v, w in adj[u]:
            nd = d + w
            if nd <= budget and nd < best[v]:
                best[v] = nd
                heapq.heappush(heap, (nd, v))
    return count
